/// <summary>
///     The <c>AVAsmmActivities_AVAKBVActivitySetFieldWorkerBtn_Extension</c> class is the execution FormControl for <c>smmActivities</c>
/// </summary>
[ExtensionOf(FormControlStr(smmActivities, AVAKBVActivitySetFieldWorker)) ]
final class AVAsmmActivities_AVAKBVActivitySetFieldWorkerBtn_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void Clicked()
{
    smmActivities                   locsmmActivities;
    HCMWorkerRecId                  locHCMWorkerRecId;
    KCS_KBVBuildingProjectID        locKCS_KBVBuildingProjectID;

    locsmmActivities            = element.smmActivities;
    locKCS_KBVBuildingProjectID = element.KCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;

    locHCMWorkerRecId   = AVAKBVBuildingProjectHelper::dialogGetFieldWorker(locKCS_KBVBuildingProjectID);  //get Worker from Dialog

    next clicked();

    if(locHCMWorkerRecId)
    {
        locsmmActivities.AVAFieldWorker         = locHCMWorkerRecId;
        locsmmActivities.AVAFieldWorkerSince    = AVAKBVBuildingProjectHelper::getToday();
    }
}
